#include <bits/stdc++.h>
using namespace std;

int main() {
    long long U; int n;
    if (scanf("%lld %d", &U, &n) != 2) return 0;
    vector<long long> w(n);
    for (auto &x : w) scanf("%lld", &x);
    vector<long long> c(w);
    sort(c.begin(), c.end());
    c.erase(unique(c.begin(), c.end()), c.end());
    int m = c.size();
    vector<int> tree(m + 1, 0);  // Fenwick tree of prefix maxima over compressed weights
    auto query = [&](int i) { int r = 0; for (; i; i -= i & -i) r = max(r, tree[i]); return r; };
    auto update = [&](int i, int v) { for (; i <= m; i += i & -i) tree[i] = max(tree[i], v); };
    int best = 0;
    for (long long x : w) {
        if (x > U) continue;
        // Longest safe subsequence ending here: predecessors with weight <= U - x.
        int prior = query(upper_bound(c.begin(), c.end(), U - x) - c.begin());
        int len = prior + 1;
        update(upper_bound(c.begin(), c.end(), x) - c.begin(), len);
        best = max(best, len);
    }
    printf("%d\n", n - best);
}

import java.io.*;
import java.util.*;

public class Main {
    static int m;
    static int[] tree;

    static int query(int i) { int r = 0; for (; i > 0; i -= i & -i) r = Math.max(r, tree[i]); return r; }
    static void update(int i, int v) { for (; i <= m; i += i & -i) tree[i] = Math.max(tree[i], v); }

    // Number of values in sorted c that are <= x.
    static int upperBound(long[] c, long x) {
        int lo = 0, hi = c.length;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (c[mid] <= x) lo = mid + 1; else hi = mid; }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.resetSyntax();
        st.wordChars('!', '~');
        st.whitespaceChars(0, ' ');
        st.nextToken(); long U = Long.parseLong(st.sval);
        st.nextToken(); int n = Integer.parseInt(st.sval);
        long[] w = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); w[i] = Long.parseLong(st.sval); }
        long[] c = Arrays.stream(w).sorted().distinct().toArray();
        m = c.length;
        tree = new int[m + 1]; // Fenwick tree of prefix maxima over compressed weights
        int best = 0;
        for (long x : w) {
            if (x > U) continue;
            // Longest safe subsequence ending here: predecessors with weight <= U - x.
            int len = query(upperBound(c, U - x)) + 1;
            update(upperBound(c, x), len);
            best = Math.max(best, len);
        }
        System.out.println(n - best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
	"sort"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var U int64
	var n int
	fmt.Fscan(in, &U, &n)
	w := make([]int64, n)
	for i := range w {
		fmt.Fscan(in, &w[i])
	}
	c := slices.Clone(w)
	slices.Sort(c)
	c = slices.Compact(c)
	m := len(c)
	tree := make([]int, m+1) // Fenwick tree of prefix maxima over compressed weights
	upper := func(x int64) int { return sort.Search(m, func(p int) bool { return c[p] > x }) }
	best := 0
	for _, x := range w {
		if x > U {
			continue
		}
		// Longest safe subsequence ending here: predecessors with weight <= U - x.
		prior := 0
		for i := upper(U - x); i > 0; i -= i & -i {
			prior = max(prior, tree[i])
		}
		length := prior + 1
		for i := upper(x); i <= m; i += i & -i {
			tree[i] = max(tree[i], length)
		}
		best = max(best, length)
	}
	fmt.Println(n - best)
}
